function simplifyType(t) {
  t = (t || '').trim();
  if (t.includes('פסקול')) return 'פסקול';
  if (t.includes('חג מולד')) return 'אלבום חג';
  if (t.includes('לייב')) return 'לייב';
  if (t.includes('אוסף')) return 'אוסף';
  if (t.includes('מיני אלבום')) return 'מיני אלבום';
  if (t.toLowerCase().includes('mixtape') || t.includes('מיקסטייפ')) return 'מיקסטייפ';
  if (t.includes('סינגל')) return 'סינגל';
  if (t.includes('אלבום סטודיו')) return 'אלבום סטודיו';
  return t || 'לא ידוע';
}

function defaultProfileForUnknown(artist) {
  if (/[\u0590-\u05FF]/.test(artist)) {
    return { genre: 'זמר עברי', energy: 3, tags: ['נוסטלגי', 'שמח'] };
  }
  return { genre: 'פופ', energy: 3, tags: ['שמח'] };
}
function defaultGenresForUnknown(artist) {
  return /[\u0590-\u05FF]/.test(artist) ? ['Israeli Pop'] : ['Pop'];
}
function parseBoolHe(v) {
  v = (v || '').trim().toLowerCase();
  return ['כן','yes','v','✓','true','1','x','כ'].includes(v);
}

// Main entry point: tag a raw record the same way the initial dataset was built.
function tagRecord({ artist, album, type: typeRaw, format, year, language, edition, color, signed, lpCount }) {
  artist = (artist || '').trim();
  album = (album || '').trim();
  const keyA = artist.toLowerCase();
  const keyAlb = `${keyA}|||${(album || '').toLowerCase()}`;
  const base = ALBUM_OVERRIDES[keyAlb] || ARTIST_PROFILES[keyA] || defaultProfileForUnknown(artist);

  const genres = GENRES[keyA] || [base.genre] || defaultGenresForUnknown(artist);
  const people = PEOPLE[keyA] || { gender: '-', act: 'סולו' };
  const popularity = POPULARITY[keyA] || 'בינוני';

  let tags = [...base.tags, ...(MOOD_ENRICH[keyA]||[]), ...(THEME_ARTIST[keyA]||[]), ...(THEME_OVERRIDES[keyAlb]||[])];
  const typeSimple = simplifyType(typeRaw);
  const isSoundtrack = typeSimple === 'פסקול';
  const isHoliday = typeSimple === 'אלבום חג' || album.includes('חג') || /christmas|santa/i.test(album);
  const isLive = typeSimple === 'לייב';
  const isHebrew = (language || '').includes('עברית');

  if (isSoundtrack && !tags.includes('פסקול')) tags.push('פסקול');
  if (isHoliday && !tags.includes('חגיגי')) tags.push('חגיגי');
  if (isLive && !tags.includes('אנרגטי')) tags.push('אנרגטי');
  tags = [...new Set(tags)];

  return {
    artist, album,
    type: typeSimple,
    format: format || '',
    year: year || '',
    language: language || '',
    genres,
    genre: base.genre,
    gender: people.gender,
    act: people.act,
    popularity,
    energy: base.energy,
    tags,
    is_soundtrack: isSoundtrack,
    is_holiday: isHoliday,
    is_live: isLive,
    is_hebrew: isHebrew,
    edition: (edition || '').trim(),
    color: (color || '').trim(),
    is_signed: parseBoolHe(signed),
    lp_count: (lpCount === undefined || lpCount === null || lpCount === '') ? '' : String(lpCount).trim(),
  };
}

